_LEGACY_ACCT_KEYS = ["device_key", "cpb_likes"]

_DEX_B64 = ""
_DEX_SHA = "47d4f4d2ef2006b97d6762babc59aed239465aeeabbd1ee4c68090f2c1466206"
_BUILD_SHA = "1a8e5fb6576c90a9b53c8e61a729d302f436d2b730a3dfc8d5569617930f70a5"

class CustomProfileBannerPlugin(BasePlugin):

    def on_plugin_load(self):
        self._core = None
        try:
            self._core = self._load_core()
        except Exception as e:
            self.log("[cpb] dex core load failed: %s" % e)
            self._core = None
        if self._core is None:
            self.log("[cpb] плагин не активен: ядро не загрузилось")

    def on_plugin_unload(self):
        core = getattr(self, "_core", None)
        if core is None:
            return
        try:
            core.unload()
        except Exception as e:
            self.log("[cpb] unload failed: %s" % e)
        self._core = None

    def _load_core(self):
        import base64
        import hashlib
        import os
        import zlib

        from java import jclass
        from org.telegram.messenger import ApplicationLoader

        ctx = ApplicationLoader.applicationContext
        if ctx is None:
            raise RuntimeError("нет контекста приложения")

        base = ctx.getFilesDir().getAbsolutePath()
        dex_dir = os.path.join(base, "cpb_native")
        os.makedirs(dex_dir, exist_ok=True)
        dex_path = os.path.join(dex_dir, "cpb_%s.dex" % _DEX_SHA[:16])

        if not os.path.exists(dex_path) or os.path.getsize(dex_path) == 0:
            # Ядро лежит в плагине сжатым: base64 раздувает содержимое на треть,
            # и несжатое оно занимало вдвое больше собственного веса.
            data = zlib.decompress(base64.b64decode(_DEX_B64))
            got = hashlib.sha256(data).hexdigest()
            if got != _DEX_SHA:
                # Ядро побилось по дороге: класть такое рядом и грузить нельзя.
                raise RuntimeError("ядро не совпало с подписью: %s" % got[:16])
            tmp = dex_path + ".part"
            with open(tmp, "wb") as f:
                f.write(data)
            os.replace(tmp, dex_path)
            for old in os.listdir(dex_dir):
                if old.endswith(".dex") and old != os.path.basename(dex_path):
                    try:
                        os.chmod(os.path.join(dex_dir, old), 0o600)
                        os.remove(os.path.join(dex_dir, old))
                    except Exception:
                        pass
        try:
            os.chmod(dex_path, 0o400)
        except Exception:
            pass

        opt_dir = os.path.join(dex_dir, "opt")
        os.makedirs(opt_dir, exist_ok=True)

        DexClassLoader = jclass("dalvik.system.DexClassLoader")
        parent = ctx.getClassLoader()
        loader = DexClassLoader(dex_path, opt_dir, None, parent)
        core = loader.loadClass("cpb.CpbNative")

        legacy = self._collect_legacy()
        load = None
        for m in core.getDeclaredMethods():
            if m.getName() == "load":
                load = m
                break
        if load is None:
            raise RuntimeError("в ядре нет метода load")
        try:
            from java import jclass
            jclass("android.util.Log").i(
                "CpbNative", "plugin build " + _DEX_SHA[:12])
        except Exception:
            pass
        load.invoke(None, _args(ctx, legacy))
        # Версию и подпись сборки знает шим, а не ядро: сообщаем их для отчётов
        # об ошибках, чтобы в диагностике было видно, какая именно сборка стоит.
        try:
            for m in core.getDeclaredMethods():
                if m.getName() == "diagBuild":
                    m.invoke(None, _args(__version__, _DEX_SHA))
                    break
        except Exception as e:
            self.log("[cpb] версия для отчётов не передана: %s" % e)
        self.log("[cpb] ядро загружено, перенесено настроек: %d" % legacy.size())
        return _Core(core)

    def _collect_legacy(self):
        from java import jclass

        HashMap = jclass("java.util.HashMap")
        out = HashMap()
        out.put("__cpb_build_sha", _BUILD_SHA)
        tag = self._acct_tag()
        missing = object()
        for key in _LEGACY_KEYS:
            for full in (tag + "_" + key, key):
                try:
                    value = self.get_setting(full, missing)
                except Exception:
                    value = missing
                if value is not missing and value is not None:
                    out.put(tag + "_" + key, self._as_java(value))
                    break
        for key in _LEGACY_ACCT_KEYS:
            try:
                value = self.get_setting(tag + "_" + key, missing)
            except Exception:
                value = missing
            if value is not missing and value is not None:
                out.put(tag + "_" + key, self._as_java(value))
        return out

    @staticmethod
    def _as_java(value):
        from java import jclass
        if isinstance(value, bool):
            return jclass("java.lang.Boolean")(bool(value))
        if isinstance(value, int):
            return jclass("java.lang.Integer")(int(value))
        if isinstance(value, float):
            return jclass("java.lang.Float")(float(value))
        return str(value)

    def _acct_tag(self):
        try:
            from hook_utils import find_class
            uc = find_class("org.telegram.messenger.UserConfig")
            acc = int(uc.selectedAccount)
            uid = int(uc.getInstance(acc).getClientUserId())
            return str(uid) if uid > 0 else ("slot%d" % acc)
        except Exception:
            return "0"

    def _t(self, ru, en):
        """
        Подпись на языке человека.

        Язык знает ядро — там же, где его выбирают, — а страница только
        спрашивает. Свой выбор языка здесь означал бы, что настройки говорят на
        одном языке, а всё остальное на другом.
        """
        try:
            return en if self._core.english() else ru
        except Exception:
            return ru

    def _flag(self, key, default=False):
        try:
            return bool(self._core.flag_of(key))
        except Exception:
            return default

    def _set_flag(self, key, value):
        try:
            self._core.flag_set(key, bool(value))
        except Exception as e:
            self.log("[cpb] настройка %s не легла: %s" % (key, e))

    def _row(self, kind, **kwargs):
        """
        Собирает строку настроек, отбрасывая то, чего не знает эта сборка.

        У разных версий клиента разный набор именованных доводов: где-то нет
        значка, где-то — своей ссылки. Строка без значка выглядит скромнее, но
        показывается; строка, собранная с чужим доводом, не показывается вовсе.
        """
        if kind is None:
            return None
        try:
            return kind(**kwargs)
        except TypeError:
            pass
        for name in ("link_alias", "icon", "subtext"):
            kwargs.pop(name, None)
            try:
                return kind(**kwargs)
            except TypeError:
                continue
        return None

    def _switch(self, key, title, hint, icon, default=False):
        """Переключатель, который правит настройку ядра, а не свою копию."""
        return self._row(
            Switch,
            key="cpb_" + key,
            text=title,
            subtext=hint,
            icon=icon,
            default=self._flag(key, default),
            link_alias=key,
            on_change=lambda value: self._set_flag(key, value),
        )

    def _lang_row(self):
        """
        Выбор языка плагина: авто, русский, английский.

        Тот же выбор есть в редакторе оформления, и настройка у них одна на
        двоих: здесь она просто на виду у тех, кто в редактор не заходит.
        """
        if Selector is None:
            return None
        modes = ("auto", "ru", "en")
        try:
            current = str(self._core.lang_mode())
        except Exception:
            current = "auto"
        at = modes.index(current) if current in modes else 0

        def choose(index):
            try:
                self._core.set_lang_mode(modes[int(index)])
            except Exception as e:
                self.log("[cpb] язык не сменился: %s" % e)

        return self._row(
            Selector,
            key="cpb_ui_lang",
            text=self._t("Язык плагина", "Plugin language"),
            default=at,
            items=[self._t("Авто", "Auto"), "Русский", "English"],
            icon="msg_translate",
            link_alias="language",
            on_change=choose,
        )

